using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CitySmoothTransitionCheck{
static CitySmoothTransitionCheck(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CitySmoothTransition.request"))return;File.Delete("CitySmoothTransition.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/NaturalDayNight/SmoothTransition.txt",e.ToString());Debug.LogException(e);}}
static void Require(bool v,string m){if(!v)throw new Exception(m);}
static void Run(){var s=SceneManager.GetActiveScene();var roots=s.GetRootGameObjects();var c=roots.SelectMany(x=>x.GetComponentsInChildren<CityDayNightController>(true)).Single();c.transitionSeconds=8;int lights=roots.Sum(x=>x.GetComponentsInChildren<Light>(true).Length);var flare=c.sunFlares.OfType<LensFlareComponentSRP>().First();c.Apply(false);float flareIntensity=flare.intensity;float sun=c.sun.intensity;float reference=-1;
foreach(int fps in new[]{30,60,120}){c.Apply(false);c.ApplyNight();float last=0;float maxStep=0;for(int i=1;i<=fps*10;i++){c.AdvanceTransition(1f/fps);Require(c.NightBlend>=last-.000001f,"Night moved backwards");maxStep=Mathf.Max(maxStep,c.NightBlend-last);last=c.NightBlend;if(i==fps){if(reference<0)reference=last;else Require(Mathf.Abs(reference-last)<.00001f,"Frame-rate-dependent timing");}}Require(c.NightBlend==1&&!c.IsTransitioning&&!flare.enabled,"Night did not settle");Require(maxStep<.025f,"Excessive per-frame jump");c.ApplyDay();for(int i=0;i<fps*10;i++)c.AdvanceTransition(1f/fps);Require(c.NightBlend==0&&!c.IsTransitioning&&flare.enabled&&Mathf.Abs(flare.intensity-flareIntensity)<.00001f&&Mathf.Abs(c.sun.intensity-sun)<.00001f,"Original day or flare not restored");}
c.Apply(false);c.ApplyNight();c.AdvanceTransition(1);float at=c.NightBlend;c.AdvanceTransition(.001f);float incoming=(c.NightBlend-at)/.001f;at=c.NightBlend;float before=c.sun.intensity;c.ApplyDay();Require(c.NightBlend==at&&c.sun.intensity==before,"Reversal changed lighting immediately");c.AdvanceTransition(.001f);float outgoing=(c.NightBlend-at)/.001f;Require(Mathf.Abs(incoming-outgoing)<.005f,"Reversal velocity jumped");c.AdvanceTransition(12);Require(c.NightBlend==0&&!c.IsTransitioning,"Reversal failed to settle");
c.PreviewBlend(.49999f);float left=RenderSettings.reflectionIntensity;float shadowLeft=c.sun.shadowStrength;c.PreviewBlend(.50001f);Require(left<.00001f&&RenderSettings.reflectionIntensity<.00001f&&shadowLeft<.00001f&&c.sun.shadowStrength<.00001f,"Reflection/shadow source exchange is visible");c.Apply(true);float endpointReflection=RenderSettings.reflectionIntensity;c.PreviewBlend(.9999f);Require(Mathf.Abs(RenderSettings.reflectionIntensity-endpointReflection)<.00001f,"Reflection endpoint pop");Require(!ShaderUtil.ShaderHasError(c.presets.night.skybox.shader),"Sky shader errors");c.Apply(false);Require(roots.Sum(x=>x.GetComponentsInChildren<Light>(true).Length)==lights,"Added lights");EditorUtility.SetDirty(c);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText("FinalEnvironmentRoadReview/NaturalDayNight/SmoothTransition.txt","SUCCESS: 8-second damped bidirectional transition checked at 30/60/120 FPS (4200 frame steps). Consistent timing; continuous velocity at midway reversal; no immediate lighting jump. Reflection and shadow exchanges occur at zero contribution; reflection endpoint matches. Original day sun and flare restored exactly. Sky shader errors=0. Light count unchanged="+lights+". Existing presets, materials and textures preserved. Saved in Day.");File.WriteAllText("CityMobileAndroidCompile.request","run");}
}

